"""Post-processing of the MPVI plan: the labeling call, the keyword cross-check and the tags (design plan 8, D4 addendum 1).

    tagged = postprocess(plan, labeler)               # plan: the paper's segments (src/mpvi_schemas.Plan); labeler: the labeling call or its stand-in
    labeler = make_stored_labeler(BEAKER_ON_HOTPLATE_LABELS)     # until the LLM is connected: the hand-written labels
    labeler = make_llm_labeler(structured_call)       # the labeling call with enforced structured output (provider PENDING)

Pipeline: planner (the hand-written plan now, the LLM later) -> postprocess() -> tagged plan -> orchestrator. The plan stays plain data (JSON), so it can be logged, cached by instruction
and replayed.

What the LABELER returns (src/mpvi_schemas.Labels, enforced by the provider's structured output and validated again here): for each manipulation segment its `primitive` (pick, place or other)
and its object phrases with roles (manipulated, destination). A reply that does not fit the schema, misses a manipulation segment, labels a navigation segment or labels one twice raises
PostprocessError: the plan stops before it starts.

What this module adds as plain code (not the LLM): the validation of the plan (src/mpvi_schemas.Plan), the `check` tag and the `group` number by the paper's rule (the last manipulation step
before a navigation step, and the last step of the plan; consecutive manipulation segments form one unit whose completion criterion is the last step's), and the keyword cross-check.

Keyword cross-check of the primitive: whole words anywhere in the description, case-insensitive: pick up / pick-up / pick / grasp / grab mean pick; place / put / set down mean place. If
the description has both a pick word and a place word the LAST match wins (it matches the end-state completion criterion, so the check triggers on the right gripper event), the segment is
tagged `ambiguous: True` and the case is logged; no match is logged (so verbs can be added once real wordings are seen). The LLM's answer is the one used; the keywords only log. A
disagreement (both gave a pick or place answer, the answers differ, or the LLM says "other" where keywords found a primitive) is logged, and with stop_on_disagreement=True (a setting, off
by default) it raises PostprocessError.

Tagged plan: {"task_name", "segments": [segment + {"index", "check", ("primitive", "objects", "group", "ambiguous", "keyword_primitive" for manipulation segments)}], "postprocess": {"log": [...]}}.
The input is not changed.

Contents:
    PostprocessError, keyword_primitive, make_stored_labeler, make_llm_labeler, postprocess.
"""

import copy
import json
import re

from pydantic import ValidationError

from src.mpvi_schemas import Labels, Plan

PRIMITIVE_WORDS = {"pick": ("pick up", "pick-up", "pick", "grasp", "grab"), "place": ("place", "put", "set down")}
_WORD_RE = re.compile(r"\b(" + "|".join(sorted((w.replace(" ", r"\s+") for ws in PRIMITIVE_WORDS.values() for w in ws), key=len, reverse=True)) + r")\b", re.IGNORECASE)
_WORD_TO_PRIMITIVE = {re.sub(r"\s+", " ", w): p for p, ws in PRIMITIVE_WORDS.items() for w in ws}


class PostprocessError(ValueError):
    """The plan or the labeling reply is not usable; the plan must not start."""


def keyword_primitive(description):
    """Finds the primitive by keywords in a description.

    Args:
        description (str): A manipulation segment's description.

    Returns:
        dict: {"primitive": "pick", "place" or None (no keyword found), "ambiguous": bool (both a pick and a place word found), "matches": list of the words found in order}.
        The last match decides the primitive.
    """
    matches = [re.sub(r"\s+", " ", m.group(1).lower()) for m in _WORD_RE.finditer(description)]
    prims = [_WORD_TO_PRIMITIVE[w] for w in matches]
    return {"primitive": prims[-1] if prims else None, "ambiguous": len(set(prims)) > 1, "matches": matches}


def make_stored_labeler(labels):
    """Builds the labeler that returns hand-written labels (until the LLM is connected, and for tests).

    Args:
        labels (dict): Labels-shaped: {"labels": [{"index", "primitive", "objects": [{"phrase", "role"}]}]}.

    Returns:
        callable: labeler(plan) -> a deep copy of `labels`.
    """
    return lambda plan: copy.deepcopy(labels)


LABEL_PROMPT = (
    "Below is a task plan as numbered segments. For every segment of type manipulation, say which primitive it maps to: pick (the gripper takes an object), place (the gripper puts the held object "
    "down) or other (neither), and list the object phrases the description refers to, each with its role: manipulated (the object acted on) or destination (the surface or place it goes to). "
    "Copy each phrase as written in the description. Answer only in the required schema; give no entry for navigation segments.\n\n{segments}")


def make_llm_labeler(structured_call):
    """Builds the labeling call on top of a provider's structured-output call.

    Args:
        structured_call (callable): structured_call(prompt: str, response_model: type) -> a Labels object or a dict, produced by the provider's native structured output or Instructor
            (provider PENDING). It must enforce the schema of `response_model` (src/mpvi_schemas.Labels). The wording of the prompt is not tuned yet.

    Returns:
        callable: labeler(plan) -> a Labels-shaped dict.
    """
    def labeler(plan):
        lines = [f"{i}. [{s['type']}] {s['description']}" for i, s in enumerate(plan["segments"])]
        reply = structured_call(LABEL_PROMPT.format(segments="\n".join(lines)), Labels)
        return reply.model_dump(mode="json") if hasattr(reply, "model_dump") else reply
    return labeler


def postprocess(plan, labeler, stop_on_disagreement=False, say=print):
    """Labels and tags a plan for the orchestrator.

    Args:
        plan (dict): The plan in the paper's format (src/mpvi_schemas.Plan).
        labeler (callable): labeler(plan) -> Labels-shaped dict (make_stored_labeler, make_llm_labeler).
        stop_on_disagreement (bool): Raise PostprocessError when the LLM's primitive and the keyword rule disagree. Defaults to False.
        say (callable): Where log lines go (one string each). Defaults to print.

    Returns:
        dict: The tagged plan (see the module docstring); its "postprocess"["log"] lists the logged cases as dicts with "kind" ("no_keyword_match", "ambiguous", "disagreement"), "segment"
        and "description".

    Raises:
        PostprocessError: If the plan or the labels do not fit their schemas, a manipulation segment is not labeled exactly once, or (with the setting) the answers disagree.
    """
    try:
        valid = Plan.model_validate(plan)
    except ValidationError as e:
        raise PostprocessError(f"the plan does not fit the schema: {e}") from e
    segs = [s.model_dump() for s in valid.segments]
    try:
        reply = labeler(json.loads(json.dumps(plan)))
        labels = Labels.model_validate(reply)
    except ValidationError as e:
        raise PostprocessError(f"the labeling reply does not fit the schema: {e}") from e
    by_index = {}
    for lab in labels.labels:
        if lab.index >= len(segs) or segs[lab.index]["type"] != "manipulation":
            raise PostprocessError(f"the labeling reply labels segment {lab.index}, which is not a manipulation segment of the plan")
        if lab.index in by_index:
            raise PostprocessError(f"the labeling reply labels segment {lab.index} twice")
        by_index[lab.index] = lab
    missing = [i for i, s in enumerate(segs) if s["type"] == "manipulation" and i not in by_index]
    if missing:
        raise PostprocessError(f"the labeling reply has no label for the manipulation segment(s) {missing}")

    log, tagged, group = [], [], -1

    def note(kind, i, text, **extra):
        log.append({"kind": kind, "segment": i, "description": segs[i]["description"], **extra})
        say(f"[postprocess] {kind} in segment {i} ({segs[i]['description']!r}): {text}")

    for i, s in enumerate(segs):
        t = {**s, "index": i, "check": False}
        if s["type"] == "manipulation":
            lab = by_index[i]
            kw = keyword_primitive(s["description"])
            if kw["primitive"] is None:
                note("no_keyword_match", i, f"no pick or place word found; the labeling says {lab.primitive.value}")
            if kw["ambiguous"]:
                note("ambiguous", i, f"words {kw['matches']}: the last decides, keywords say {kw['primitive']}; the labeling says {lab.primitive.value}")
            if kw["primitive"] is not None and lab.primitive.value != kw["primitive"]:
                note("disagreement", i, f"the labeling says {lab.primitive.value}, the keywords say {kw['primitive']}", llm=lab.primitive.value, keywords=kw["primitive"])
                if stop_on_disagreement:
                    raise PostprocessError(f"segment {i} ({s['description']!r}): the labeling says {lab.primitive.value}, the keywords say {kw['primitive']}")
            if i == 0 or segs[i - 1]["type"] != "manipulation":
                group += 1
            t.update(primitive=lab.primitive.value, objects=[o.model_dump(mode="json") for o in lab.objects], group=group, ambiguous=kw["ambiguous"], keyword_primitive=kw["primitive"],
                     check=i == len(segs) - 1 or segs[i + 1]["type"] != "manipulation")
        tagged.append(t)
    return {"task_name": valid.task_name, "segments": tagged, "postprocess": {"log": log}}
